for (let i = 0; i < 40; i++) {
  const text = await promptText();
  if (text === '[E] Enter ship') break;
  if (text === '[E] Open cargo') {
    // inside the 3–5 m zone of the docked ship, already aligned (the cone
    // covers it) — a short W burst closes the last < 2 m to the near zone.
    await touch(page, 'move', { thrust: 1 });
    await page.waitForTimeout(250);
    await touch(page, 'move', { thrust: 0 });
    await charSettled(page);
    continue;
  }
  const p = await charPos(page);
  const f = await charForward(page);
  ...
  if (Math.abs(angle) < 0.4 && dist > 3.2) {
    // aligned, far: W burst sized to land in the near zone
    await touch(page, 'move', { thrust: 1 });
    await page.waitForTimeout(Math.min(2_000, Math.max(200, ((dist - 3.2) / 3) * 1000)));
    await touch(page, 'move', { thrust: 0 });
  } else {
    ... yaw nudge
  }
  await charSettled(page);
}
```

Wait, one nuance: the W burst lands at about 3.2 m, which is inside the Open cargo zone (3–5 m). Then the Open cargo branch does a 250 ms W burst (0.75 m) → lands at about 2.45 m → near zone → 'Enter ship'. Good.

